I'm working on implementing the Myers diff algorithm in JavaScript for character-level diffs. I've got the basic implementation down, but I'm running into an issue where sometimes the diffs are incorrect at the ends of the strings. I'm looking for some advice on how to avoid this "wrong end" problem.

Here's the code snippet I have so far:

```javascript
function myersDiff(a, b) {
    const dp = Array(b.length + 1).fill(null).map(() => Array(a.length + 1).fill(0));
    const snake = Array(b.length + 1).fill(null).map(() => Array(a.length + 1).fill(0));

    for (let i = 0; i <= b.length; i++) {
        dp[i][0] = i;
    }
    for (let j = 0; j <= a.length; j++) {
        dp[0][j] = j;
    }

    for (let i = 1; i <= b.length; i++) {
        for (let j = 1; j <= a.length; j++) {
            if (b[i - 1] === a[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1];
                snake[i][j] = 'd';
            } else {
                if (dp[i - 1][j] < dp[i][j - 1]) {
                    dp[i][j] = dp[i - 1][j] + 1;
                    snake[i][j] = 'u';
                } else {
                    dp[i][j] = dp[i][j - 1] + 1;
                    snake[i][j] = 'l';
                }
            }
        }
    }

    // Backtrack to find the diff
    let i = b.length, j = a.length;
    const diff = [];
    while (i > 0 || j > 0) {
        if (snake[i][j] === 'd') {
            diff.push({ type: 'match', value: a[j - 1] });
            i--;
            j--;
        } else if (snake[i][j] === 'u') {
            diff.push({ type: 'insert', value: b[i - 1] });
            i--;
        } else if (snake[i][j] === 'l') {
            diff.push({ type: 'delete', value: a[j - 1] });
            j--;
        }
    }

    return diff.reverse();
}

const a = "hello";
const b = "hallo";
console.log(myersDiff(a, b));
```

